// Deduplicate by record id and fill missing numeric/text fields with safe defaults
const seen = new Set();
const cleaned = [];
for (const item of items) {
  const d = item.json;
  const key = d.id || JSON.stringify(d);
  if (seen.has(key)) continue;
  seen.add(key);
  d.revenue = d.revenue ?? 0;
  d.jobs = d.jobs ?? 0;
  d.rating = d.rating ?? null;
  d.customerName = d.customerName || 'Unknown';
  cleaned.push({ json: d });
}
return cleaned;

// Normalize date formats (ISO) and currency (2 decimal USD)
return items.map(item => {
  const d = item.json;
  if (d.date) d.date = new Date(d.date).toISOString().split('T')[0];
  if (typeof d.revenue === 'number') d.revenue = Math.round(d.revenue * 100) / 100;
  return { json: d };
});

const all = items.map(i => i.json);
const today = new Date().toISOString().split('T')[0];
const todayRevenue = all.filter(d => d.date === today).reduce((s,d)=>s+(d.revenue||0),0);
const weekAgo = new Date(Date.now()-7*24*60*60*1000).toISOString().split('T')[0];
const weeklyRevenue = all.filter(d => d.date >= weekAgo).reduce((s,d)=>s+(d.revenue||0),0);
const monthAgo = new Date(Date.now()-30*24*60*60*1000).toISOString().split('T')[0];
const monthlyRevenue = all.filter(d => d.date >= monthAgo).reduce((s,d)=>s+(d.revenue||0),0);
return [{ json: { ...items[0]?.json, todayRevenue, weeklyRevenue, monthlyRevenue, records: all } }];

const d = items[0].json;
const records = d.records || [];
const jobsCompleted = records.filter(r=>r.status==='completed').length;
const openJobs = records.filter(r=>r.status==='open').length;
const cancelledJobs = records.filter(r=>r.status==='cancelled').length;
const bookings = records.filter(r=>r.type==='booking').length;
const pendingEstimates = records.filter(r=>r.estimateStatus==='pending').length;
const approvedEstimates = records.filter(r=>r.estimateStatus==='approved').length;
const rejectedEstimates = records.filter(r=>r.estimateStatus==='rejected').length;
const totalEstimates = pendingEstimates+approvedEstimates+rejectedEstimates;
const estimateConversion = totalEstimates ? Math.round((approvedEstimates/totalEstimates)*1000)/10 : 0;
const bookingRate = records.length ? Math.round((bookings/records.length)*1000)/10 : 0;
d.jobsCompleted=jobsCompleted; d.openJobs=openJobs; d.cancelledJobs=cancelledJobs; d.bookings=bookings;
d.pendingEstimates=pendingEstimates; d.approvedEstimates=approvedEstimates; d.rejectedEstimates=rejectedEstimates;
d.estimateConversion=estimateConversion; d.bookingRate=bookingRate;
return [{ json: d }];

const d = items[0].json;
const records = d.records || [];
const completed = records.filter(r=>r.status==='completed');
const avgTicket = completed.length ? Math.round((completed.reduce((s,r)=>s+(r.revenue||0),0)/completed.length)*100)/100 : 0;
const revenuePerJob = avgTicket;
const techs = [...new Set(records.map(r=>r.technicianId).filter(Boolean))];
const revenuePerTechnician = techs.length ? Math.round((d.monthlyRevenue/techs.length)*100)/100 : 0;
d.avgTicket = avgTicket; d.revenuePerJob = revenuePerJob; d.revenuePerTechnician = revenuePerTechnician;
return [{ json: d }];

const d = items[0].json;
const records = d.records || [];
const sources = {};
for (const r of records) {
  const src = r.leadSource || 'Unknown';
  sources[src] = sources[src] || { total: 0, booked: 0 };
  sources[src].total++;
  if (r.type === 'booking') sources[src].booked++;
}
const leadSourceBreakdown = Object.entries(sources).map(([source, v]) => ({
  source, total: v.total, bookingRate: v.total ? Math.round((v.booked/v.total)*1000)/10 : 0
}));
leadSourceBreakdown.sort((a,b)=>b.bookingRate-a.bookingRate);
d.leadSourceBreakdown = leadSourceBreakdown;
d.bestPerformingSource = leadSourceBreakdown[0]?.source || 'N/A';
d.worstPerformingSource = leadSourceBreakdown[leadSourceBreakdown.length-1]?.source || 'N/A';
return [{ json: d }];

const d = items[0].json;
const records = d.records || [];
const techMap = {};
for (const r of records.filter(r=>r.status==='completed')) {
  const t = r.technicianName || r.technicianId || 'Unassigned';
  techMap[t] = techMap[t] || { jobs: 0, revenue: 0, ratings: [] };
  techMap[t].jobs++;
  techMap[t].revenue += (r.revenue||0);
  if (r.rating) techMap[t].ratings.push(r.rating);
}
const leaderboard = Object.entries(techMap).map(([name, v]) => ({
  name, jobs: v.jobs, revenue: Math.round(v.revenue*100)/100,
  avgTicket: v.jobs ? Math.round((v.revenue/v.jobs)*100)/100 : 0,
  avgRating: v.ratings.length ? Math.round((v.ratings.reduce((s,x)=>s+x,0)/v.ratings.length)*10)/10 : null
}));
leaderboard.sort((a,b)=>b.revenue-a.revenue);
d.technicianLeaderboard = leaderboard;
d.topTechnician = leaderboard[0]?.name || 'N/A';
d.lowestPerformer = leaderboard[leaderboard.length-1]?.name || 'N/A';
return [{ json: d }];

const d = items[0].json;
const reviews = d.reviews || d.records.filter(r=>r.rating!==undefined && r.rating!==null) || [];
const newReviews = reviews.length;
const avgRating = reviews.length ? Math.round((reviews.reduce((s,r)=>s+(r.rating||0),0)/reviews.length)*10)/10 : 0;
const negativeReviews = reviews.filter(r=>r.rating<=3).length;
const positiveReviews = reviews.filter(r=>r.rating>=4).length;
const previousAvg = d.previousAvgRating || avgRating;
const reviewGrowth = Math.round((avgRating - previousAvg)*100)/100;
d.newReviews=newReviews; d.avgRating=avgRating; d.negativeReviews=negativeReviews;
d.positiveReviews=positiveReviews; d.reviewGrowth=reviewGrowth;
return [{ json: d }];

const d = items[0].json;
const revenueTarget = d.revenueTarget || 5000;
const revenueScore = Math.min(25, (d.todayRevenue/revenueTarget)*25);
const bookingScore = Math.min(20, (d.bookingRate/100)*20);
const conversionScore = Math.min(20, (d.estimateConversion/100)*20);
const reviewScore = Math.min(20, (d.avgRating/5)*20);
const repeatScore = Math.min(15, ((d.repeatCustomerRate||0)/100)*15);
const healthScore = Math.round(revenueScore+bookingScore+conversionScore+reviewScore+repeatScore);
d.businessHealthScore = healthScore;
d.healthScoreExplanation = `Score built from: Revenue ${Math.round(revenueScore)}/25, Bookings ${Math.round(bookingScore)}/20, Estimate Conversion ${Math.round(conversionScore)}/20, Reviews ${Math.round(reviewScore)}/20, Repeat Customers ${Math.round(repeatScore)}/15.`;
return [{ json: d }];

const prev = $('Business Health Score').first().json;
let aiText = items[0].json.choices?.[0]?.message?.content || '{}';
let parsed = {};
try { parsed = JSON.parse(aiText); } catch(e) { parsed = { businessSummary: aiText }; }
return [{ json: { ...prev, ai: parsed } }];

const rows = items.map(i=>i.json);
const weeklyRevenue = rows.reduce((s,r)=>s+(Number(r.revenue)||0),0);
return [{ json: { weeklyRevenue, rowCount: rows.length, rows } }];

const rows = items.map(i=>i.json);
const monthlyRevenue = rows.reduce((s,r)=>s+(Number(r.revenue)||0),0);
const monthlyBookings = rows.filter(r=>r.type==='booking').length;
return [{ json: { monthlyRevenue, monthlyBookings, rows } }];

const e = items[0].json;
return [{ json: {
  workflow: e.workflow?.name || 'HVAC Executive Dashboard',
  errorMessage: e.execution?.error?.message || e.trigger?.error?.message || 'Unknown error',
  timestamp: new Date().toISOString(),
  nodeName: e.execution?.error?.node?.name || 'Unknown node'
}}];
